using System;
using System.Collections.Generic;
using System.Linq;

namespace BrassPatch.Statistics
{
    // Additional factual measures, with explicit units and historical boundaries.
    public static class StatisticsDetailMetrics
    {
        public static double Median(IEnumerable<int> source)
        {var values=source.OrderBy(x=>x).ToArray();return values.Length==0?Double.NaN:(values[(values.Length-1)/2]+values[values.Length/2])/2.0;}
        public static IEnumerable<StatisticsSection> Build(CompletedMatchStatistics r,StatisticsFilters f,int page)
        {
            var output=new List<StatisticsSection>();if(!r.CompleteHistory)return output;
            Func<string,string,string[],StatisticsSection> section=(title,definition,columns)=>{var s=new StatisticsSection(title,definition,columns);output.Add(s);return s;};
            var assets=StatisticsMetrics.Assets(r,f).ToArray();var actions=StatisticsMetrics.Actions(r,f).ToArray();
            if(page==2||page==8){
                var delay=section("Completion delay by industry","Built cohort, filtered by flip era. Unflipped tiles do not contribute a fake delay of zero. Medians state their sample size.",new[]{"Industry","Flipped sample","Median own turns","Median global turns","Unflipped cohort"});
                foreach(var type in StatisticsPages.IndustryTypes){var cohort=assets.Where(a=>a.Type==type).ToArray();var flipped=cohort.Where(a=>a.Flipped&&(f.Era==0||f.Era==a.FlipEra)).ToArray();delay.Rows.Add(new StatisticsRow("delay-"+type,"Owner-turn delay counts only that player's turns; global delay counts every player's turn.",StatisticsMetrics.IndustryName(type),flipped.Length.ToString(),Number(Median(flipped.Select(a=>a.FlipOwnTurn-a.OwnTurn))),Number(Median(flipped.Select(a=>a.FlipTurn-a.Turn))),cohort.Count(a=>!a.Flipped).ToString()));}
                var unfinished=section("Unfinished investment at era boundaries","Historical state at scoring, not final flags reused for Canal. Printed VP is nominal; suppliers may already have provided resources or market cash.",new[]{"Player","Boundary","Tile / city","Own-turn age","Cash invested","Nominal printed VP","Stock / supplied / receipts"});
                foreach(var a in r.Assets.Where(a=>f.Players.Contains(a.Player)&&(f.Industry==""||a.Type==f.Industry)&&(f.Region==""||a.RegionColor==f.Region)&&(!f.EvidenceRestricted&&f.Evidence.Count==0||f.Evidence.Contains(a.Key))))foreach(var era in r.Introductory?new[]{1}:new[]{1,2}){
                    if(f.Era!=0&&f.Era!=era)continue;var b=StatisticsMetrics.Boundary(r,a.Player,"Scoring",era);if(!StatisticsMetrics.At(a,b)||a.FlipRevision>0&&a.FlipRevision<=b.Revision)continue;
                    var stock=r.Stocks.FirstOrDefault(s=>s.AssetKey==a.Key&&s.Revision==b.Revision);
                    var supplied=r.Entries.Where(e=>e.AssetKey==a.Key&&e.Revision<=b.Revision&&e.Kind=="Resource use").Sum(e=>e.Quantity);
                    var receipts=r.Entries.Where(e=>e.AssetKey==a.Key&&e.Revision<=b.Revision&&e.Kind=="Market sale").Sum(e=>e.TotalPrice);
                    unfinished.Rows.Add(new StatisticsRow(a.Key,a.Sellable?"Unconverted goods; sale feasibility was not probed.":"Unflipped supplier; useful service is recorded separately.",r.Name(a.Player),era==1?"Canal scoring":"Rail scoring",StatisticsMetrics.IndustryName(a.Type)+" L"+a.Level+" · "+a.City,(b.OwnTurn-a.OwnTurn).ToString(),StatisticsFormat.Money(a.BaseCost+a.MarketCost),a.PrintedVP.ToString(),(stock==null?"—":stock.Stock.ToString())+" / "+supplied+" / "+StatisticsFormat.Money(receipts)){Player=a.Player});
                }
                output.AddRange(new StatisticsSection[0]);
            }
            if(page==4){
                var usefulness=section("Income gains and remaining paydays","Recorded paydays strictly after each income-level gain in the same era. This counts opportunities, not hypothetical extra earnings attributed to a tile.",new[]{"Player","Income gain","Own turn","Remaining era paydays","Recorded later income cash"});
                foreach(var e in StatisticsMetrics.Entries(r,f).Where(e=>e.Kind=="Balance"&&e.Income>0)){var paydays=r.Entries.Where(p=>p.Kind=="Payday"&&p.Player==e.Player&&p.Era==e.Era&&p.Revision>e.Revision).ToArray();var paid=r.Entries.Where(p=>p.Kind=="Balance"&&p.Category=="Income payment"&&p.Player==e.Player&&p.Era==e.Era&&p.Revision>e.Revision).Sum(p=>Math.Max(0,p.Cash));usefulness.Rows.Add(new StatisticsRow("entry-"+e.Revision+"-"+e.Player,e.Position+" · "+e.Label+". Cash is total income paid later, not a causal allocation to this gain.",r.Name(e.Player),"+"+e.Income+" income levels",e.OwnTurn.ToString(),paydays.Length.ToString(),StatisticsFormat.Money(paid)){Player=e.Player});}
                var late=section("Last own turns and cash conversion","Final cash affects tie-breaks; introductory additional scoring is kept separate. Actual actions are shown without assuming a better legal purchase existed.",new[]{"Player","Final cash","Last four actions","Cash spent","Recorded action-time VP"});
                foreach(var p in r.Players.Where(p=>f.Players.Contains(p.Color))){var last=actions.Where(a=>a.Player==p.Color).Reverse().Take(4).Reverse().ToArray();int vp=last.Sum(a=>r.Entries.Where(e=>e.Player==p.Color&&e.Revision>=a.Revision&&e.Revision<=a.EndRevision&&e.Kind=="Balance").Sum(e=>e.VP));late.Rows.Add(new StatisticsRow("late-"+p.Color,r.Introductory?"Introductory cash/income/additional tile points are final awards, not ordinary sale VP.":"Most industry and link VP is awarded at the scoring boundary after the actions.",p.Name,StatisticsFormat.Money(p.FinalCash),String.Join(" → ",last.Select(a=>a.Kind)),StatisticsFormat.Money(last.Sum(a=>a.Spending)),vp.ToString()){Player=p.Color});}
            }
            if(page==5&&!f.Outgoing){
                var beer=section("Brewery supply and demand","Beer for Sell and Network uses is counted separately. Remaining or removed stock is not automatically waste. Units supplied ties are permitted.",new[]{"Player","Self / opponents used","Beer consumed (own / opponent / merchant)","Sell / Network use","Remaining / removed stock"});
                foreach(var p in r.Players.Where(p=>f.Players.Contains(p.Color))){var uses=r.Entries.Where(e=>e.Kind=="Resource use"&&e.Resource=="Beer"&&(f.Era==0||e.Era==f.Era)).ToArray();var breweries=assets.Where(a=>a.Player==p.Color&&a.Type=="Brewery").ToArray();beer.Rows.Add(new StatisticsRow("beer-"+p.Color,"Brewery suppliers can flip from opponents' demand. Stock on a removed asset records its state at removal.",p.Name,uses.Where(e=>e.Supplier==p.Color&&e.Player==p.Color).Sum(e=>e.Quantity)+" / "+uses.Where(e=>e.Supplier==p.Color&&e.Player!=p.Color).Sum(e=>e.Quantity),uses.Where(e=>e.Player==p.Color&&e.Supplier==p.Color).Sum(e=>e.Quantity)+" / "+uses.Where(e=>e.Player==p.Color&&e.Supplier.HasValue&&e.Supplier!=p.Color).Sum(e=>e.Quantity)+" / "+uses.Where(e=>e.Player==p.Color&&e.Source=="Merchant").Sum(e=>e.Quantity),uses.Where(e=>e.Player==p.Color&&e.Category=="Sell").Sum(e=>e.Quantity)+" / "+uses.Where(e=>e.Player==p.Color&&e.Category=="Network").Sum(e=>e.Quantity),breweries.Where(a=>a.Remaining).Sum(a=>a.Stock)+" / "+breweries.Where(a=>!a.Remaining).Sum(a=>a.Stock)){Player=p.Color});}
                var dependence=section("Market dependence and paid unit prices","Purchase prices are typed totals. Purchases enrich cost attribution; they are not added a second time to action spending.",new[]{"Player","Resource","Market units / all consumed","Market share","Paid total","£ / unit"});
                foreach(var p in r.Players.Where(p=>f.Players.Contains(p.Color)))foreach(var resource in new[]{"Coal","Iron"}){var purchases=r.Entries.Where(e=>e.Player==p.Color&&e.Resource==resource&&e.Kind=="Market purchase"&&(f.Era==0||e.Era==f.Era)).ToArray();int units=purchases.Sum(e=>e.Quantity);int total=r.Entries.Where(e=>e.Player==p.Color&&e.Resource==resource&&e.Kind=="Resource use"&&(f.Era==0||e.Era==f.Era)).Sum(e=>e.Quantity);dependence.Rows.Add(new StatisticsRow("dependence-"+p.Color+resource,"The denominator counts supplied units, including market deliveries; units bought but not consumed are not expected in normal completed actions.",p.Name,resource,units+" / "+total,StatisticsFormat.Percent(units,total),StatisticsFormat.Money(purchases.Sum(e=>e.TotalPrice)),StatisticsFormat.Ratio(purchases.Sum(e=>e.TotalPrice),units)){Player=p.Color});}
                var coverage=section("Merchant sale attribution coverage","Unique observed destinations and uniquely derivable destinations are distinguishable. Unattributed sales remain a separate group; their location is never guessed.",new[]{"Player","Sales","Recorded destination","Uniquely derived","Unattributed"});
                foreach(var p in r.Players.Where(p=>f.Players.Contains(p.Color))){var sold=StatisticsMetrics.Entries(r,f).Where(e=>e.Player==p.Color&&e.Kind=="Goods sale").ToArray();coverage.Rows.Add(new StatisticsRow("coverage-"+p.Color,"Only known destinations support a location-specific merchant profile.",p.Name,sold.Length.ToString(),sold.Count(e=>e.Destination!="Unattributed"&&!e.DestinationDerived).ToString(),sold.Count(e=>e.DestinationDerived).ToString(),sold.Count(e=>e.Destination=="Unattributed").ToString()){Player=p.Color});}
            }
            if(page==6){
                var batch=section("Sell action efficiency","Goods tiles per confirmed Sell action. Scout trades and merchant Develop bonuses do not add actions.",new[]{"Player","Sell actions","Goods sold","Tiles / Sell","Largest batch","Multi-tile sales"});
                foreach(var p in r.Players.Where(p=>f.Players.Contains(p.Color))){var sold=actions.Where(a=>a.Player==p.Color&&a.Kind=="Sell").ToArray();batch.Rows.Add(new StatisticsRow("batch-"+p.Color,"The same industry's VP is never credited to Build and Sell as two independent returns.",p.Name,sold.Length.ToString(),sold.Sum(a=>a.Goods).ToString(),StatisticsFormat.Ratio(sold.Sum(a=>a.Goods),sold.Length),sold.Select(a=>a.Goods).DefaultIfEmpty().Max().ToString(),sold.Count(a=>a.Goods>=2).ToString()){Player=p.Color});}
                var wild=section("Wildcard acquisition → use episodes","A wildcard can be re-acquired after returning to the pool. Each episode is separate; unused flexibility is not proof Scout was unnecessary.",new[]{"Player","Wild card","Acquired own turn","Used after own / global turns","Purpose","Unused at finish"});
                foreach(var e in StatisticsMetrics.Entries(r,f).Where(e=>e.Kind=="Wildcard acquired")){var use=r.Entries.FirstOrDefault(x=>x.Kind=="Card"&&x.AssetKey=="wild@"+e.Revision&&x.Player==e.Player);var action=use==null?null:r.Actions.FirstOrDefault(a=>a.Key==use.ActionKey);wild.Rows.Add(new StatisticsRow("entry-"+e.Revision+"-"+e.Player,e.Position,e.Kind=="Wildcard acquired"?r.Name(e.Player):"",e.Category,e.OwnTurn.ToString(),use==null?"—":(use.OwnTurn-e.OwnTurn)+" / "+(use.Turn-e.Turn),action==null?"—":action.Kind,use==null?"Yes":"No"){Player=e.Player});}
            }
            return output;
        }
        static string Number(double value){return Double.IsNaN(value)?"—":value.ToString("0.##",System.Globalization.CultureInfo.InvariantCulture);}
    }
}
